using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CraftTradeTests
{
 static readonly EntityId Site=new("site:sakai"),Owner=new("created:port-house"),Gun=new("craft:group/gun");
 internal static WorldSession Start()=>PublicWorksTests.PortStart();
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static CraftInput Input(WorldSession s,CraftAction action,EntityId? reference=null,string good="iron",long quantity=1,EntityId? destination=null)=>new(new("request:craft/"+s.Revision),action,Owner,Site,reference,destination,good,quantity);
 internal static WorldSession Hired(){var s=Start();Good(s.ManageCraft(Input(s,CraftAction.MeetGroup,Gun),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:Site),s.Revision));return s;}
 [Fact]public void HiringRequiresActualMeetingAndAcceptedConditionsWithoutCreatingWarriors(){var s=Start();var before=s.DiagnosticSnapshot();Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:Site),s.Revision).Code);Good(s.ManageCraft(Input(s,CraftAction.MeetGroup,Gun),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:Site) with{Housing=false},s.Revision));Assert.Null(CraftTrade.Position(s.DiagnosticSnapshot(),Gun).Owner);Good(s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:Site),s.Revision));Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.True(NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl)<1000);Assert.Equal(Owner,CraftTrade.Position(s.DiagnosticSnapshot(),Gun).Owner);Assert.Equal(ContractJson.Write(before.Characters),ContractJson.Write(s.DiagnosticSnapshot().Characters));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(s.DiagnosticSnapshot().Memberships));}
 [Fact]public void NoGunsWithoutWorkshopRawMaterialsAndProductionTime(){var s=Hired();Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Produce,Gun,"gun"),s.Revision).Code);Good(s.StartPublicWork(new(new("request:craft-workshop"),Site,WorksKind.Workshop),s.Revision));NewGameWorldTests.At(s,7*86400);Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Produce,Gun,"gun"),s.Revision).Code);Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"iron",quantity:2),s.Revision));Assert.Equal(98,CraftTrade.MerchantStock(s.DiagnosticSnapshot(),Site,"iron"));var i=Input(s,CraftAction.Produce,Gun,"gun");Good(s.ManageCraft(i,s.Revision));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"gun"));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"iron"));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCraft(i,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Produce,Gun,"gun"),s.Revision).Code);NewGameWorldTests.At(s,14*86400);Assert.Equal(1,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"gun"));}
 [Fact]public void CrewAndCargoCannotBeSoldOrSettledBeforeRealReturn(){var s=ShipReady();long cash=s.HouseTreasuryView()!.HouseCash,wood=s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Site).Wood;var ship=PublicWorks.Ships(s.DiagnosticSnapshot()).Single();Good(s.ManageCraft(Input(s,CraftAction.MeetMerchant),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.LaunchVoyage,ship.Id,"wood",5),s.Revision));Assert.Equal(cash-10,s.HouseTreasuryView()!.HouseCash);Assert.Equal(wood-5,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Site).Wood);Assert.Equal(90,s.CommunityEconomyView()!.Accounts.Workforce);var v=CraftTrade.Voyages(s.DiagnosticSnapshot()).Single();Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.ReturnVoyage,v.Id),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.LaunchVoyage,ship.Id,"wood",5),s.Revision).Code);NewGameWorldTests.At(s,v.ReturnAt!.Value);Assert.Equal("帰港・決済済み",CraftTrade.Voyages(s.DiagnosticSnapshot()).Single().Phase);Assert.Equal(cash-10+40,s.HouseTreasuryView()!.HouseCash);Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);}
 internal static WorldSession ShipReady(){var s=Start();Good(s.StartPublicWork(new(new("request:craft-port"),Site,WorksKind.Port),s.Revision));NewGameWorldTests.At(s,7*86400);Good(s.StartPublicWork(new(new("request:craft-ship"),Site,WorksKind.TradeShip),s.Revision));NewGameWorldTests.At(s,21*86400);var ship=PublicWorks.Ships(s.DiagnosticSnapshot()).Single();Good(s.MaintainPublicShip(new("request:craft-ship-care"),ship.Id,s.Revision));return s;}
 [Fact]public void MissionPermissionAndPersonalFaithDoNotTransferLandMembershipOrArmy(){var s=Start();var w=s.DiagnosticSnapshot();Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.JoinFaith),s.Revision).Code);Good(s.ManageCraft(Input(s,CraftAction.PermitMission),s.Revision));Assert.False(CraftTrade.Christian(s.DiagnosticSnapshot(),s.PlayerControl));Good(s.ManageCraft(Input(s,CraftAction.JoinFaith),s.Revision));Assert.True(CraftTrade.Christian(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ContractJson.Write(w.LandRights),ContractJson.Write(s.DiagnosticSnapshot().LandRights));Assert.Equal(ContractJson.Write(w.Memberships),ContractJson.Write(s.DiagnosticSnapshot().Memberships));Assert.Equal(ContractJson.Write(w.ServiceBonds),ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));Assert.Equal(ContractJson.Write(w.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));}
 [Fact]public void OldWorldDoesNotAcquireInventedGoodsOrChangeBytes(){var w=Start().DiagnosticSnapshot();var b=ContractJson.Write(w);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));w.Crafts=new(1,CraftTrade.Policy,[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void LoadingAndUnloadingMovesTheSameMaterialAndCannotDuplicateIt(){var s=Start();Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"iron",quantity:5),s.Revision));var i=Input(s,CraftAction.Load,good:"iron",quantity:5);Good(s.ManageCraft(i,s.Revision));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"iron"));Assert.Single(CraftTrade.Carried(s.DiagnosticSnapshot(),s.PlayerControl));Good(s.ManageCraft(Input(s,CraftAction.Unload,i.Id),s.Revision));Assert.Equal(5,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"iron"));Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Unload,i.Id),s.Revision).Code);}

 static WorldSession TwoSites(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:port-lord",StartTemplate.Daimyo,"site:sakai")],[new("created:port-lord","created:port-house",["site:sakai","site:kofu"],false)]);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:port-lord",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));}
 static WorldSession Restore(WorldSession s){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"craft-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"mid",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("mid"),host.Current,host.Current.Revision));return host.Current;}
 [Fact]public void CraftGroupActuallyTravelsAndMidJourneySaveHasSameArrival(){var s=TwoSites();Good(s.ManageCraft(Input(s,CraftAction.MeetGroup,Gun),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:new("site:kofu")),s.Revision));var arrival=CraftTrade.Position(s.DiagnosticSnapshot(),Gun).ArrivalAt!.Value;Assert.True(arrival>s.Seconds);Assert.NotEqual(new EntityId("site:kofu"),CraftTrade.Position(s.DiagnosticSnapshot(),Gun).Site);NewGameWorldTests.At(s,1);var other=Restore(s);foreach(var x in new[]{s,other})NewGameWorldTests.At(x,arrival);Assert.Equal(new EntityId("site:kofu"),CraftTrade.Position(s.DiagnosticSnapshot(),Gun).Site);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(other.DiagnosticSnapshot()));}
 [Fact]public void ClosureStopsTheActualGroupAndResumeDoesNotPayOrCloneItAgain(){var s=TwoSites();Good(s.ManageCraft(Input(s,CraftAction.MeetGroup,Gun),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Hire,Gun,destination:new("site:kofu")),s.Revision));var w=s.DiagnosticSnapshot();var first=w.Crafts!.Entries.Last().Legs[0];w.Couriers=w.Couriers! with{InitialBlocked=[first.Edge],Conditions=[new(10,first.Edge,false)]};w.Branches=w.Branches! with{BlockedEdges=[first.Edge]};s=new(w);Assert.True(CraftTrade.Position(w,Gun).Stopped);long coins=NewGameWork.Balance(w,s.PlayerControl);NewGameWorldTests.At(s,11);Good(s.ManageCraft(Input(s,CraftAction.ResumeGroup,Gun,destination:new("site:kofu")),s.Revision));Assert.False(CraftTrade.Position(s.DiagnosticSnapshot(),Gun).Stopped);Assert.Equal(coins,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Single(s.DiagnosticSnapshot().Crafts!.Entries,e=>e.Input.Action==CraftAction.Hire&&e.Accepted);}
 [Fact]public void ProductionMidSaveRestoresTheSameMaterialsAndFinishedGun(){var s=Hired();Good(s.StartPublicWork(new(new("request:save-workshop"),Site,WorksKind.Workshop),s.Revision));NewGameWorldTests.At(s,7*86400);Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"iron",quantity:2),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Produce,Gun,"gun"),s.Revision));NewGameWorldTests.At(s,8*86400);var other=Restore(s);foreach(var x in new[]{s,other})NewGameWorldTests.At(x,14*86400);Assert.Equal(1,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"gun"));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(other.DiagnosticSnapshot()));}
 [Fact]public void BlockedDepartureCanReturnTheSameCargoWithoutCreatingProfit(){var s=ShipReady();Good(s.ManageCraft(Input(s,CraftAction.MeetMerchant),s.Revision));var ship=PublicWorks.Ships(s.DiagnosticSnapshot()).Single();Good(s.ManageCraft(Input(s,CraftAction.LaunchVoyage,ship.Id,"wood",5),s.Revision));var w=s.DiagnosticSnapshot();var voyage=w.Crafts!.Entries.Last();string edge=voyage.Legs[0].Edge;w.Couriers=w.Couriers! with{Conditions=[new(voyage.Legs[0].StartAt,edge,true)]};s=new(w);NewGameWorldTests.At(s,voyage.Legs[0].StartAt);Assert.Equal("運休・寄港待機",CraftTrade.Voyages(s.DiagnosticSnapshot()).Single().Phase);long wood=s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Site).Wood,cash=s.HouseTreasuryView()!.HouseCash;var other=Restore(s);foreach(var x in new[]{s,other})Good(x.ManageCraft(Input(x,CraftAction.CancelVoyage,voyage.Input.Id),x.Revision));Assert.Equal(wood+5,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Site).Wood);Assert.Equal(cash,s.HouseTreasuryView()!.HouseCash);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(other.DiagnosticSnapshot()));}
 [Fact]public void ReturnClosureDelaysRevenueUntilTheRealReopeningAndReturn(){var s=ShipReady();Good(s.ManageCraft(Input(s,CraftAction.MeetMerchant),s.Revision));var ship=PublicWorks.Ships(s.DiagnosticSnapshot()).Single();Good(s.ManageCraft(Input(s,CraftAction.LaunchVoyage,ship.Id,"wood",5),s.Revision));var w=s.DiagnosticSnapshot();var voyage=w.Crafts!.Entries.Last();long close=voyage.Legs[1].StartAt,open=close+2*86400;w.Couriers=w.Couriers! with{Conditions=[new(close,voyage.Legs[1].Edge,true),new(open,voyage.Legs[1].Edge,false)]};s=new(w);NewGameWorldTests.At(s,voyage.Due);Assert.Equal("航海中",CraftTrade.Voyages(s.DiagnosticSnapshot()).Single().Phase);Assert.Equal(voyage.Due+2*86400,CraftTrade.Voyages(s.DiagnosticSnapshot()).Single().ReturnAt);long cash=s.HouseTreasuryView()!.HouseCash;var other=Restore(s);foreach(var x in new[]{s,other})NewGameWorldTests.At(x,voyage.Due+2*86400);Assert.Equal(cash+40,s.HouseTreasuryView()!.HouseCash);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(other.DiagnosticSnapshot()));}

 static void Npc(WorldSession s,Action<ContractWorld> action)=>typeof(WorldSession).GetMethod("Change",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.Invoke(s,[action,null]);
 [Fact]public void NpcHeadActuallyMeetsHiresBuysAndStartsProductionThroughTheSameLedger(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:port-lord",StartTemplate.Daimyo,"site:sakai"),NewGameWorldTests.Officer("created:craft-observer",StartTemplate.Ronin,"site:sakai")],[new("created:port-lord","created:port-house",["site:sakai"],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:craft-observer",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));Npc(s,w=>PublicWorks.Execute(w,new(new("request:npc-craft-workshop"),Site,WorksKind.Workshop),new("created:port-lord")));Good(s.ManageCraft(Input(s,CraftAction.MeetGroup,Gun),s.Revision));for(int n=0;n<8;n++)NewGameWorldTests.At(s,7*86400+n);var es=s.DiagnosticSnapshot().Crafts!.Entries.Where(e=>e.Actor==new EntityId("created:port-lord")).ToArray();Assert.Contains(es,e=>e.Input.Action==CraftAction.Hire&&e.Accepted);Assert.Contains(es,e=>e.Input.Action==CraftAction.Buy);Assert.Contains(es,e=>e.Input.Action==CraftAction.Produce);}
 [Fact]public void ForeignAccessNeedsActualLocalContactAndPowderConsumesAllThreeMaterials(){var s=Hired();Good(s.StartPublicWork(new(new("request:powder-workshop"),Site,WorksKind.Workshop),s.Revision));NewGameWorldTests.At(s,7*86400);Assert.Equal(ResultCode.NotAvailable,s.ManageCraft(Input(s,CraftAction.Buy,good:"saltpeter",quantity:2),s.Revision).Code);Good(s.ManageCraft(Input(s,CraftAction.PermitMission),s.Revision));Assert.False(CraftTrade.Christian(s.DiagnosticSnapshot(),s.PlayerControl));Assert.False(CraftTrade.ForeignAccess(s.DiagnosticSnapshot(),s.PlayerControl,Site));Good(s.ManageCraft(Input(s,CraftAction.MeetMerchant),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"saltpeter",quantity:2),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"sulfur"),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"charcoal"),s.Revision));Good(s.ManageCraft(Input(s,CraftAction.Produce,Gun,"powder"),s.Revision));foreach(var k in new[]{"saltpeter","sulfur","charcoal"})Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,k));NewGameWorldTests.At(s,10*86400);Assert.Equal(2,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"powder"));}
 [Fact]public void MineAndRefiningConsumeActualOreAfterFacilityAndWorkTime(){var owner=new EntityId("org:takeda");var site=new EntityId("site:kofu");var group=new EntityId("craft:group/mining");var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(),[],"person:shingen",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));CraftInput I(CraftAction a,string good="iron")=>new(new("request:mine-craft/"+s.Revision),a,owner,site,group,site,good);Good(s.ManageCraft(I(CraftAction.MeetGroup),s.Revision));Good(s.ManageCraft(I(CraftAction.Hire),s.Revision));Good(s.StartPublicWork(new(new("request:working-mine"),site,WorksKind.Mine),s.Revision));NewGameWorldTests.At(s,7*86400);Good(s.ManageCraft(I(CraftAction.Produce,"ore"),s.Revision));NewGameWorldTests.At(s,14*86400);Assert.Equal(5,CraftTrade.Stock(s.DiagnosticSnapshot(),owner,site,"ore"));Good(s.ManageCraft(I(CraftAction.Produce,"gold"),s.Revision));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),owner,site,"ore"));NewGameWorldTests.At(s,21*86400);Assert.Equal(1,CraftTrade.Stock(s.DiagnosticSnapshot(),owner,site,"gold"));}
 [Fact]public void PersonallyCarriedRawMaterialsReachOnlyTheActualDestinationAfterSave(){var s=TwoSites();Good(s.ManageCraft(Input(s,CraftAction.Buy,good:"iron",quantity:5),s.Revision));var load=Input(s,CraftAction.Load,good:"iron",quantity:5);Good(s.ManageCraft(load,s.Revision));var move=TravelWorld.Move(s.DiagnosticSnapshot(),"request:craft-cargo-trip","kofu");Good(s.Submit(move,s.Revision));NewGameWorldTests.At(s,1);var other=Restore(s);long finish=move.DeliverySeconds+move.WorkSeconds+10;foreach(var x in new[]{s,other}){NewGameWorldTests.At(x,finish);var i=new CraftInput(new("request:actual-ore-delivery"),CraftAction.Unload,Owner,new("site:kofu"),load.Id);Good(x.ManageCraft(i,x.Revision));}Assert.Equal(5,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,new("site:kofu"),"iron"));Assert.Equal(0,CraftTrade.Stock(s.DiagnosticSnapshot(),Owner,Site,"iron"));Assert.Empty(CraftTrade.Carried(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(other.DiagnosticSnapshot()));}
}
